/**
 * Server-side offline ASR runtime powered by sherpa-onnx (WebAssembly build).
 *
 * Runs NVIDIA NeMo models that transformers.js cannot execute:
 *   - Canary 180M Flash      (offline, EN/ES/DE/FR, ~207MB)
 *   - Parakeet TDT 0.6B v3   (streaming, EN, ~670MB)
 *   - Nemotron 3.5 Streaming (streaming, 40 locales, ~680MB)
 *
 * Everything is processed locally — no cloud APIs involved.
 */
import fs from "fs";
import path from "path";
import { createRequire } from "module";
import type { Request, Response } from "express";

// Lazy require so the server still boots if the package fails to load.
const require = createRequire(import.meta.url);
const sherpa = require("sherpa-onnx") as any;

const MODELS_DIR = path.join(process.cwd(), "models", "sherpa");

export interface SherpaModelDef {
  id: string;
  label: string;
  kind: "offline-canary" | "online-transducer";
  repo: string;
  files: string[];
  langs: string[];
  modelType: string; // sherpa-onnx C API model_type
}

export const SHERPA_MODELS: Record<string, SherpaModelDef> = {
  "sherpa-onnx:canary-180m-flash": {
    id: "sherpa-onnx:canary-180m-flash",
    label: "Canary 180M Flash (EN/ES/DE/FR)",
    kind: "offline-canary",
    repo: "csukuangfj/sherpa-onnx-nemo-canary-180m-flash-en-es-de-fr-int8",
    files: ["encoder.int8.onnx", "decoder.int8.onnx", "tokens.txt"],
    langs: ["en", "es", "de", "fr"],
    modelType: "canary",
  },
  "sherpa-onnx:parakeet-tdt-0.6b": {
    id: "sherpa-onnx:parakeet-tdt-0.6b",
    label: "Parakeet TDT 0.6B v3 (EN, streaming)",
    kind: "online-transducer",
    repo: "csukuangfj/sherpa-onnx-nemo-parakeet-tdt-0.6b-v3-int8",
    files: ["encoder.int8.onnx", "decoder.int8.onnx", "joiner.int8.onnx", "tokens.txt"],
    langs: ["en"],
    modelType: "nemo",
  },
  "sherpa-onnx:nemotron-3.5-streaming": {
    id: "sherpa-onnx:nemotron-3.5-streaming",
    label: "Nemotron 3.5 ASR Streaming 0.6B (40 locales)",
    kind: "online-transducer",
    repo: "csukuangfj2/sherpa-onnx-nemotron-3.5-asr-streaming-0.6b-1120ms-int8-2026-06-11",
    files: ["encoder.int8.onnx", "decoder.int8.onnx", "joiner.int8.onnx", "tokens.txt"],
    langs: [
      "en", "es", "fr", "de", "it", "pt", "nl", "ru", "ar", "hi", "ja", "ko",
      "vi", "uk", "pl", "sv", "cs", "da", "fi", "zh", "hu", "ro", "el", "he",
      "th", "tr", "bg", "hr", "sk", "et", "lt", "lv", "mt", "sl", "nn", "no",
    ],
    modelType: "nemotron",
  },
};

/* ── Download gateways (automatic fallback, no user choice needed) ── */
const GATEWAYS = [
  "https://huggingface.co",
  "https://hf-mirror.com",
  "https://hf.co",
  "https://cdn-media.huggingface.co",
];

/**
 * Fetches through every gateway in order until one succeeds. A mirror that
 * is slow, blocked, or down mid-transfer never blocks the download.
 */
async function gatewayFetch(repoPath: string, init?: RequestInit): Promise<Response> {
  let lastErr: Error | null = null;
  for (const g of GATEWAYS) {
    try {
      const resp = await fetch(`${g}/${repoPath}`, init);
      if (resp.ok) return resp;
      lastErr = new Error(`HTTP ${resp.status} from ${g}`);
    } catch (err: any) {
      lastErr = err;
    }
  }
  throw lastErr ?? new Error("All download gateways failed");
}

export function sherpaAvailable(): boolean {
  try {
    return !!sherpa?.createOfflineRecognizer && !!sherpa?.version;
  } catch {
    return false;
  }
}

function modelDir(def: SherpaModelDef): string {
  return path.join(MODELS_DIR, def.id.replace("sherpa-onnx:", ""));
}

export function modelDownloaded(id: string): boolean {
  const def = SHERPA_MODELS[id];
  if (!def) return false;
  const dir = modelDir(def);
  return def.files.every((f) => {
    try {
      return fs.statSync(path.join(dir, f)).size > 0;
    } catch {
      return false;
    }
  });
}

function totalModelBytes(def: SherpaModelDef): number {
  const dir = modelDir(def);
  let total = 0;
  for (const f of def.files) {
    try {
      total += fs.statSync(path.join(dir, f)).size;
    } catch {}
  }
  return total;
}

/* ── Download state (progress is polled by the settings UI) ── */
const downloads = new Map<
  string,
  { done: number; total: number; status: "downloading" | "done" | "error"; error?: string }
>();

export function getDownloadProgress(id: string) {
  return downloads.get(id) || null;
}

export async function startModelDownload(id: string): Promise<{ ok: boolean; error?: string }> {
  const def = SHERPA_MODELS[id];
  if (!def) return { ok: false, error: "Unknown model" };
  if (modelDownloaded(id)) {
    downloads.set(id, { done: totalModelBytes(def), total: totalModelBytes(def), status: "done" });
    return { ok: true };
  }
  if (downloads.get(id)?.status === "downloading") return { ok: true };

  const dir = modelDir(def);
  fs.mkdirSync(dir, { recursive: true });
  downloads.set(id, { done: 0, total: 0, status: "downloading" });

  // Total = sum of all file sizes (HEAD requests, gateway fallback).
  let total = 0;
  try {
    for (const f of def.files) {
      const head = await gatewayFetch(`${def.repo}/resolve/main/${f}`, { method: "HEAD" });
      const sz = Number(head.headers.get("x-linked-size") || head.headers.get("content-length") || 0);
      total += sz;
    }
  } catch {}
  downloads.set(id, { done: 0, total, status: "downloading" });

  try {
    for (const f of def.files) {
      const dest = path.join(dir, f);
      if (fs.existsSync(dest) && fs.statSync(dest).size > 0) continue;
      // Try each gateway in order; move on automatically when one fails.
      let ok = false;
      let attempts = 0;
      while (!ok && attempts < GATEWAYS.length * 3) {
        attempts++;
        try {
          const resp = await gatewayFetch(`${def.repo}/resolve/main/${f}`);
          if (!resp.ok || !resp.body) throw new Error(`HTTP ${resp.status}`);
          const fileSize = Number(resp.headers.get("x-linked-size") || resp.headers.get("content-length") || 0);
          const out = fs.createWriteStream(dest + ".part");
          let received = 0;
          // `completedBefore` = bytes of files finished in earlier iterations.
          const completedBefore = downloads.get(id)!.done;
          const reader = resp.body.getReader();
          for (;;) {
            const { done, value } = await reader.read();
            if (done) break;
            out.write(Buffer.from(value));
            received += value.byteLength;
            downloads.set(id, {
              ...downloads.get(id)!,
              done: completedBefore + received,
              status: "downloading",
            });
          }
          out.end();
          await new Promise<void>((resolve, reject) => {
            out.on("finish", () => resolve());
            out.on("error", reject);
          });
          if (fileSize && received < fileSize * 0.99) throw new Error(`short download ${received}/${fileSize}`);
          fs.renameSync(dest + ".part", dest);
          ok = true;
        } catch (err: any) {
          fs.rmSync(dest + ".part", { force: true });
          if (attempts >= GATEWAYS.length * 3) throw err;
        }
      }
    }
    downloads.set(id, { done: totalModelBytes(def), total, status: "done" });
    return { ok: true };
  } catch (err: any) {
    downloads.set(id, { done: 0, total, status: "error", error: err.message });
    return { ok: false, error: err.message };
  }
}

/* ── Session state (streaming chunks from the browser) ── */
interface Session {
  id: string;
  def: SherpaModelDef;
  lang: string;
  audioChunks: Float32Array[]; // offline models: accumulated audio since last finalize
  audioBytes: number;
  recognizer: any;
  stream: any;
  lastTouch: number;
}

const sessions = new Map<string, Session>();
let sessionSeq = 0;

function cleanupSessions(): void {
  const now = Date.now();
  for (const [id, s] of sessions) {
    if (now - s.lastTouch > 10 * 60 * 1000) {
      try { s.stream?.free(); } catch {}
      try { s.recognizer?.free(); } catch {}
      sessions.delete(id);
    }
  }
}
setInterval(cleanupSessions, 5 * 60 * 1000).unref?.();

function buildRecognizer(def: SherpaModelDef, lang: string): { recognizer: any; stream: any } {
  const dir = modelDir(def);
  const base = (f: string) => path.join(dir, f);
  if (def.kind === "offline-canary") {
    const recognizer = sherpa.createOfflineRecognizer({
      modelConfig: {
        canary: {
          encoder: base("encoder.int8.onnx"),
          decoder: base("decoder.int8.onnx"),
          srcLang: lang,
          tgtLang: lang,
          usePnc: 1,
        },
        debug: 0,
        tokens: base("tokens.txt"),
      },
    });
    return { recognizer, stream: recognizer.createStream() };
  }
  // online transducer (parakeet-tdt / nemotron)
  const recognizer = sherpa.createOnlineRecognizer({
    featConfig: { sampleRate: 16000, featureDim: 80 },
    modelConfig: {
      transducer: {
        encoder: base("encoder.int8.onnx"),
        decoder: base("decoder.int8.onnx"),
        joiner: base("joiner.int8.onnx"),
      },
      tokens: base("tokens.txt"),
      numThreads: 1,
      provider: "cpu",
      debug: 0,
      modelType: def.modelType,
      modelingUnit: "",
      bpeVocab: "",
    },
    decodingMethod: "greedy_search",
    maxActivePaths: 4,
    enableEndpoint: 0,
    rule1MinTrailingSilence: 2.4,
    rule2MinTrailingSilence: 1.2,
    rule3MinUtteranceLength: 20,
    hotwordsFile: "",
    hotwordsScore: 1.5,
    ctcFstDecoderConfig: { graph: "", maxActive: 3000 },
    ruleFsts: "",
    ruleFars: "",
  });
  return { recognizer, stream: recognizer.createStream() };
}

function pickLang(def: SherpaModelDef, requested: string | undefined): string {
  const base = (requested || "en").split("-")[0].toLowerCase();
  if (def.langs.includes(base)) return base;
  if (def.langs.includes("en")) return "en";
  return def.langs[0] || "en";
}

export function startSession(id: string, requestedLang?: string): { sessionId: string; lang: string; fallback: boolean } {
  const def = SHERPA_MODELS[id];
  const lang = pickLang(def, requestedLang);
  const sessionId = `s${Date.now()}-${sessionSeq++}`;
  const { recognizer, stream } = buildRecognizer(def, lang);
  sessions.set(sessionId, {
    id: sessionId,
    def,
    lang,
    audioChunks: [],
    audioBytes: 0,
    recognizer,
    stream,
    lastTouch: Date.now(),
  });
  return { sessionId, lang, fallback: lang !== (requestedLang || "en").split("-")[0].toLowerCase() && !!requestedLang };
}

export function sessionExists(sessionId: string): boolean {
  return sessions.has(sessionId);
}

export function endSession(sessionId: string): void {
  const s = sessions.get(sessionId);
  if (!s) return;
  try { s.stream?.free(); } catch {}
  try { s.recognizer?.free(); } catch {}
  sessions.delete(sessionId);
}

/** Feed one chunk of 16kHz mono Float32 samples. Returns current hypothesis. */
export function feedAudio(sessionId: string, samples: Float32Array): { text: string; error?: string } {
  const s = sessions.get(sessionId);
  if (!s) return { text: "", error: "Unknown session" };
  s.lastTouch = Date.now();
  try {
    if (s.def.kind === "offline-canary") {
      s.audioChunks.push(samples);
      s.audioBytes += samples.byteLength;
      const total = s.audioChunks.reduce((n, c) => n + c.length, 0);
      const audio = new Float32Array(total);
      let off = 0;
      for (const c of s.audioChunks) {
        audio.set(c, off);
        off += c.length;
      }
      s.stream.acceptWaveform(16000, audio);
      s.recognizer.decode(s.stream);
      const text = s.recognizer.getResult(s.stream).text;
      // Reuse the stream for the next pass (offline streams are stateless per decode).
      s.stream.free();
      s.stream = s.recognizer.createStream();
      return { text };
    }
    // online transducer: append + decode incrementally
    s.stream.acceptWaveform(16000, samples);
    s.recognizer.decode(s.stream);
    return { text: s.recognizer.getResult(s.stream).text };
  } catch (err: any) {
    return { text: "", error: err.message };
  }
}

/** Finalize the current utterance (VAD endpoint). Clears per-utterance state. */
export function finalizeSession(sessionId: string): { text: string; error?: string } {
  const s = sessions.get(sessionId);
  if (!s) return { text: "", error: "Unknown session" };
  s.lastTouch = Date.now();
  try {
    let text = "";
    if (s.def.kind === "offline-canary") {
      if (s.audioChunks.length) {
        const total = s.audioChunks.reduce((n, c) => n + c.length, 0);
        const audio = new Float32Array(total);
        let off = 0;
        for (const c of s.audioChunks) {
          audio.set(c, off);
          off += c.length;
        }
        s.audioChunks = [];
        s.audioBytes = 0;
        s.stream.acceptWaveform(16000, audio);
        s.recognizer.decode(s.stream);
        text = s.recognizer.getResult(s.stream).text;
        s.stream.free();
        s.stream = s.recognizer.createStream();
      }
    } else {
      text = s.recognizer.getResult(s.stream).text;
      // Fresh stream for the next utterance (avoid text duplication).
      s.stream.free();
      s.stream = s.recognizer.createStream();
    }
    return { text };
  } catch (err: any) {
    return { text: "", error: err.message };
  }
}

/* ── Express routes ── */

export function sherpaStatus(): any {
  return {
    available: sherpaAvailable(),
    version: sherpaAvailable() ? sherpa.version : null,
    models: Object.values(SHERPA_MODELS).map((def) => ({
      id: def.id,
      label: def.label,
      kind: def.kind,
      langs: def.langs,
      downloaded: modelDownloaded(def.id),
    })),
  };
}

export async function handleDownload(req: Request, res: Response): Promise<void> {
  const { model } = req.body || {};
  if (!SHERPA_MODELS[model]) {
    res.status(400).json({ error: "Unknown model" });
    return;
  }
  const result = await startModelDownload(model);
  res.json(result);
}

export function handleProgress(req: Request, res: Response): void {
  const { model } = req.query;
  res.json(getDownloadProgress(String(model)));
}

export function handleSession(req: Request, res: Response): void {
  try {
    const { action } = req.query;
    const model = String(req.query.model || "");
    const lang = String(req.query.lang || "en");
    const sessionId = String(req.query.sessionId || "");

    if (action === "start") {
      if (!SHERPA_MODELS[model]) {
        res.status(400).json({ error: "Unknown model" });
        return;
      }
      if (!modelDownloaded(model)) {
        res.status(409).json({ error: "Model not downloaded" });
        return;
      }
      const info = startSession(model, lang);
      res.json({ ok: true, ...info });
      return;
    }

    if (action === "finalize") {
      if (!sessionExists(sessionId)) {
        res.status(404).json({ error: "Unknown session" });
        return;
      }
      res.json({ ok: true, ...finalizeSession(sessionId) });
      return;
    }

    if (action === "cancel") {
      endSession(sessionId);
      res.json({ ok: true });
      return;
    }

    if (action === "audio") {
      if (!sessionExists(sessionId)) {
        res.status(404).json({ error: "Unknown session" });
        return;
      }
      const body: Buffer = (req as any).body;
      if (!body || body.byteLength < 4 || body.byteLength % 4 !== 0) {
        res.status(400).json({ error: "Expected raw Float32 PCM body" });
        return;
      }
      const samples = new Float32Array(body.buffer, body.byteOffset, body.byteLength / 4);
      const result = feedAudio(sessionId, samples);
      if (result.error) {
        res.status(500).json({ error: result.error });
        return;
      }
      res.json({ ok: true, text: result.text });
      return;
    }

    res.status(400).json({ error: "Unknown action" });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
}